      // Teamspace: pipeline milik tim (NULL = pipeline ops biasa)
      division: varchar("division", { length: 32 }),
      // Divisi pemilik (hrd|noc|dst) - pipeline kerja per divisi (NULL = pipeline ops global)
      createdBy: int("created_by").notNull(),
      updatedBy: int("updated_by"),
