      footer: text("footer"),
      // Footer text (small grey text di bawah message)
      buttons: text("buttons"),
      // JSON array of buttons [{type, label, payload}]
      mediaUrl: text("media_url"),
      // URL gambar / video untuk attach
      mediaType: text("media_type"),
      // "image" | "video" | "document"
      // v4.2.20: PRD WA Feature v2 - template type + customer filter + reseller share
      templateType: varchar("template_type", { length: 255 }).default("pelanggan"),
      // pelanggan | reseller | system
      templateChannel: varchar("template_channel", { length: 255 }).default("unofficial"),
      // unofficial | official (mengikuti tab di PRD)
      customerFilter: varchar("customer_filter", { length: 255 }).default("all"),
      // all | unpaid (saat broadcast pelanggan)
      shareToReseller: int("share_to_reseller").default(0),
