            const now = (/* @__PURE__ */ new Date()).toISOString();
            const [ins] = await this.pool.execute(
              `INSERT INTO pipelines (mitra_id, name, description, created_by, created_at) VALUES (1, 'Rekrutmen Kandidat', 'Pipeline kandidat pelamar (PRD-HR FR-HR-1003) - pindahkan kartu antar tahapan', 1, ?)`,
              [now]
            );
            const pid = ins.insertId;
            const stages = [["Lamaran Masuk", "#0EA5E9"], ["Screening", "#F59E0B"], ["Interview", "#8B5CF6"], ["Offer", "#10B981"], ["Diterima", "#22C55E"], ["Ditolak", "#94A3B8"]];
            for (let i = 0; i < stages.length; i++) {
              await this.pool.execute(
                `INSERT INTO pipeline_stages (mitra_id, pipeline_id, label, color, position, created_at) VALUES (1, ?, ?, ?, ?, ?)`,
                [pid, stages[i][0], stages[i][1], i, now]
              );
            }
            console.log(`[migration] Seeded pipeline Rekrutmen Kandidat (#${pid})`);
