          lng: r.lng != null ? Number(r.lng) : null,
          odpId: r.odpId != null ? Number(r.odpId) : null,
          severity: r.severity ? String(r.severity) : "info",
          createdAt: String(r.createdAt),
          hasPhoto: Boolean(Number(r.hasPhoto)),
