var COVERAGE_RADIUS_METERS = 250;
router.post("/api/coverage-check", async (req, res) => {
  try {
    const lat = Number(req.body?.lat);
    const lng = Number(req.body?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return sendError(res, "Koordinat tidak valid");
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return sendError(res, "Koordinat di luar range");
    const allOdps = await storage.getOdps();
    const validOdps = allOdps.filter((o) => o.lat != null && o.lng != null);
    if (validOdps.length === 0) {
      return sendSuccess(res, {
        target: { lat, lng },
        coverageRadiusMeters: COVERAGE_RADIUS_METERS,
        nearestOdps: [],
        recommended: null,
        message: "Belum ada data ODP"
      });
    }
    const ranked = validOdps.map((o) => {
      const distance = Math.round(haversineDistance2(lat, lng, o.lat, o.lng));
      const capacity = o.capacity ?? 8;
      const used = o.usedCapacity ?? 0;
      const available = Math.max(0, capacity - used);
      return {
        id: o.id,
        name: o.name,
        code: o.code,
        lat: o.lat,
        lng: o.lng,
        address: o.address,
        district: o.district,
        village: o.village,
        splitterType: o.splitterType,
        status: o.status,
        capacity,
        usedCapacity: used,
        availablePorts: available,
        distanceMeters: distance,
        inCoverage: distance <= COVERAGE_RADIUS_METERS
      };
    }).sort((a, b) => a.distanceMeters - b.distanceMeters);
    const nearestOdps = ranked.slice(0, 5);
    const { calculatePowerBudget: calculatePowerBudget2, POWER_BUDGET: POWER_BUDGET2 } = await Promise.resolve().then(() => (init_schema2(), schema_exports));
    const recommendedRaw = ranked.find((o) => o.availablePorts > 0 && o.status === "active") ?? ranked[0];
    let recommended = null;
    if (recommendedRaw) {
      const splitter = recommendedRaw.splitterType || "1:8";
      const fiberKm = recommendedRaw.distanceMeters / 1e3;
      const power = calculatePowerBudget2({
        fiberKm,
        splices: 2,
        connectors: 2,
        splitters: [splitter]
      });
      recommended = {
        ...recommendedRaw,
        powerBudget: {
          ...power,
          assumptions: {
            fiberKm: Math.round(fiberKm * 1e3) / 1e3,
            splices: 2,
            connectors: 2,
            splitters: [splitter],
            gponOutputDbm: POWER_BUDGET2.gponOutput,
            rxSensitivityDbm: POWER_BUDGET2.rxSensitivity,
            rxMaxTargetDbm: POWER_BUDGET2.rxMaxTarget
          }
        }
      };
    }
    const closest = nearestOdps[0];
    const verdict = closest.inCoverage && closest.availablePorts > 0 ? "covered" : closest.inCoverage && closest.availablePorts === 0 ? "covered_full" : closest.distanceMeters <= COVERAGE_RADIUS_METERS * 2 ? "marginal" : "out_of_coverage";
    sendSuccess(res, {
      target: { lat, lng },
      coverageRadiusMeters: COVERAGE_RADIUS_METERS,
      verdict,
      nearestOdps,
      recommended
    });
  } catch (e) {
    sendError(res, e.message, 500);
  }
});
