router.get("/api/odps/:id/detail", async (req, res) => {
  if (!requirePermission(req, res, "map")) return;
  try {
    const id = Number(req.params.id);
    const odp = await storage.getOdp(id);
    if (!odp) return sendError(res, "ODP tidak ditemukan", 404);
    const custs = await storage.getCustomersByOdp(id);
    const capacity = odp.capacity || 8;
    const used = custs.length;
    const counts = { total: custs.length, active: 0, isolir: 0, suspend: 0, terminated: 0, unknown: 0 };
    const customersOut = custs.map((c) => {
      const st = customerConnStatus(c);
      counts[st]++;
      return {
        id: c.id,
        customerId: c.customerId,
        name: c.name,
        connStatus: st,
        package: c.package,
        portNumber: c.portNumber,
        ontSerialNumber: c.ontSerialNumber,
        phone: c.phone
      };
    });
    sendSuccess(res, {
      odp: {
        id: odp.id,
        name: odp.name,
        code: odp.code,
        splitterType: odp.splitterType,
        status: odp.status,
        address: odp.address,
        district: odp.district,
        village: odp.village,
        lat: odp.lat,
        lng: odp.lng
      },
      utilization: {
        capacity,
        used,
        available: Math.max(0, capacity - used),
        pct: capacity > 0 ? Math.min(Math.round(used / capacity * 100), 100) : 0
      },
      counts,
      customers: customersOut
    });
  } catch (e) {
    sendError(res, e.message, 500);
  }
});
