function requireAuth(req, res) {
  if (!req.authUser) {
    sendError(res, "Unauthorized - silakan login terlebih dahulu", 401);
    return false;
  }
  return true;
}
function toCSV(data, columns) {
  const header = columns.map((c) => c.label).join(",");
  const rows = data.map(
    (row) => columns.map((c) => {
      const val2 = row[c.key];
      if (val2 === null || val2 === void 0) return "";
      const str2 = String(val2);
      if (str2.includes(",") || str2.includes("\n") || str2.includes("\r") || str2.includes('"')) {
        return `"${str2.replace(/"/g, '""')}"`;
      }
      return str2;
    }).join(",")
  );
  return [header, ...rows].join("\n");
}
