router.post("/api/loyalty/admin/statement/broadcast", async (req, res) => {
  if (!req.authUser) return sendError(res, "Unauthorized", 401);
  if (!hasWritePermission(req, "loyalty_admin")) return sendError(res, "Akses ditolak (write)", 403);
  try {
    const top = await storage.getLoyaltyLeaderboard(200, "referrals");
    const targets = top.filter((l) => (l.totalSuccessfulReferrals ?? 0) > 0);
    let sent = 0;
    let failed = 0;
    for (const t of targets) {
      const r = await sendSahabatMonthlyStatement(t.customerId).catch(() => ({ sent: false }));
      if (r.sent) sent++;
      else failed++;
    }
    await logAudit(req, "BROADCAST", "sahabat_statement", void 0, `${sent}/${targets.length}`);
    sendSuccess(res, { attempted: targets.length, sent, failed });
  } catch (e) {
    sendError(res, e.message, 500);
  }
});
async function sendSahabatMonthlyStatement(customerId) {
  const customer = await storage.getCustomer(customerId);
  if (!customer?.phone) return { sent: false, reason: "no_phone" };
  const loyalty = await storage.getOrCreateCustomerLoyalty(customerId);
  const now = /* @__PURE__ */ new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59).toISOString();
  const allRefs = await storage.getReferralsByCustomer(customerId);
  const thisMonthRefs = allRefs.filter((r) => r.createdAt >= monthStart && r.createdAt <= monthEnd);
  const thisMonthRewarded = allRefs.filter((r) => r.rewardCreditedAt && r.rewardCreditedAt >= monthStart && r.rewardCreditedAt <= monthEnd);
  const rank = await storage.getLoyaltyLeaderboard(500, "referrals").then(
    (top) => top.findIndex((x) => x.customerId === customerId) + 1 || null
  );
  const monthLabel = now.toLocaleDateString("id-ID", { month: "long", year: "numeric" });
  const { sendLoyaltyNotification: sendLoyaltyNotification2 } = await Promise.resolve().then(() => (init_mpwa(), mpwa_exports));
  const totalSuccessful = loyalty.totalSuccessfulReferrals ?? 0;
  const LEVEL_LABEL = {
    new: "Pelanggan",
    perunggu: "Perunggu ",
    perak: "Perak ",
    emas: "Emas ",
    platinum: "Platinum ",
    berlian: "Berlian ",
    ambassador: "Ambassador "
  };
  const level = loyalty.sahabatLevel ?? "new";
  const result = await sendLoyaltyNotification2("sahabat_monthly_statement", customer.phone, {
    nama: customer.name,
    month: monthLabel,
    thisMonthInvited: String(thisMonthRefs.length),
    thisMonthRewarded: String(thisMonthRewarded.length),
    totalSuccessful: String(totalSuccessful),
    level: LEVEL_LABEL[level] ?? level,
    rank: rank ? `#${rank}` : "-",
    sahabatCode: loyalty.sahabatCode ?? loyalty.referralCode ?? "-"
  });
  return { sent: result.sent, reason: result.error };
}
