router.post("/api/loyalty/admin/points/redemptions/expire-overdue", async (req, res) => {
  if (!req.authUser) return sendError(res, "Unauthorized", 401);
  if (!hasWritePermission(req, "loyalty_admin")) return sendError(res, "Akses ditolak (write)", 403);
  try {
    const overdue = await storage.getOverdueActiveRedemptions();
    let success = 0, failed = 0;
    const failures = [];
    if (overdue.length > 0) {
      const { revertBoost: revertBoost2 } = await Promise.resolve().then(() => (init_mikrotik_boost(), mikrotik_boost_exports));
      const { sendLoyaltyNotification: sendLoyaltyNotification2 } = await Promise.resolve().then(() => (init_mpwa(), mpwa_exports));
      for (const r of overdue) {
        if (r.originalPppProfile) {
          const result = await revertBoost2(r.customerId, r.originalPppProfile).catch((e) => ({ success: false, error: e.message }));
          if (!result.success) {
            await storage.recordRevertFailure(r.id, result.error ?? "unknown");
            failed++;
            failures.push({ id: r.id, error: result.error ?? "unknown" });
            continue;
          }
        }
        await storage.markRevertedAndExpired(r.id);
        success++;
        try {
          const customer = await storage.getCustomer(r.customerId);
          if (customer?.phone) {
            const loyalty = await storage.getOrCreateCustomerLoyalty(r.customerId);
            await sendLoyaltyNotification2("sahabat_boost_expired", customer.phone, {
              nama: customer.name,
              rewardLabel: r.rewardLabel,
              normalPackage: customer.package || "paket berlangganan",
              lifetimeEarned: String(loyalty.pointsLifetimeEarned ?? 0),
              balance: String(loyalty.pointsBalance ?? 0)
            });
          }
        } catch (e) {
          console.warn("[Boost] manual expire WA:", e.message);
        }
      }
    }
    await logAudit(req, "EXPIRE", "point_redemptions", void 0, `${success} expired, ${failed} failed revert`);
    sendSuccess(res, { processed: overdue.length, expired: success, revertFailed: failed, failures });
  } catch (e) {
    sendError(res, e.message, 500);
  }
});
