router.post("/api/marketing/leads/:id/convert", async (req, res) => {
  if (!req.authUser) return sendError(res, "Unauthorized", 401);
  try {
    const leadId = Number(req.params.id);
    const lead = await storage.getLeadById(leadId);
    if (!lead) return sendError(res, "Lead tidak ditemukan", 404);
    const allCustomers = await storage.getCustomers();
    const alreadyConverted = allCustomers.find((c) => c.leadId === leadId);
    if (alreadyConverted) {
      return sendError(res, `Lead sudah dikonversi menjadi pelanggan ${alreadyConverted.customerId}`, 400);
    }
    const { customerId, package: pkg, pppoeUsername, pppoePassword, pppoeProfile, pppoeRouterId, createWorkOrder } = req.body;
    if (!customerId) return sendError(res, "ID Pelanggan (billing) wajib diisi");
    if (!pkg) return sendError(res, "Paket layanan wajib diisi");
    const categoryMap = { rumahan: "rumahan", bisnis: "bisnis", sekolah: "bisnis", perkantoran: "bisnis", lainnya: "bisnis" };
    const customerType = categoryMap[lead.category || ""] || "rumahan";
    let portNumber;
    if (lead.odpId) {
      const usedPorts = new Set(
        allCustomers.filter((c) => c.odpId === lead.odpId && c.portNumber).map((c) => c.portNumber)
      );
      const odp = await storage.getOdp(lead.odpId);
      const cap = odp?.capacity || 8;
      for (let p = 1; p <= cap; p++) {
        if (!usedPorts.has(p)) {
          portNumber = p;
          break;
        }
      }
    }
    const customer = await storage.createCustomer({
      name: lead.name,
      customerId,
      phone: lead.phone || void 0,
      address: lead.address || void 0,
      lat: lead.lat ?? void 0,
      lng: lead.lng ?? void 0,
      district: lead.district || void 0,
      village: lead.village || void 0,
      odpId: lead.odpId ?? void 0,
      portNumber,
      package: pkg,
      status: "active",
      customerType,
      pppoeUsername: pppoeUsername || void 0,
      pppoePassword: pppoePassword || void 0,
      pppoeProfile: pppoeProfile || void 0,
      pppoeRouterId: pppoeRouterId || void 0,
      leadId
    });
    let pppoeSync;
    if (customer.pppoeUsername && customer.pppoePassword && customer.pppoeRouterId) {
      pppoeSync = await syncPppoeToMikrotik(customer, "create");
      if (pppoeSync.success && pppoeSync.mikrotikId) {
        await storage.updateCustomer(customer.id, { pppoeMikrotikId: pppoeSync.mikrotikId });
      }
    }
    if (lead.stage !== "won") {
      await storage.moveLeadStage(leadId, "won", req.authUser.id);
    }
    await storage.createLeadActivity({
      leadId,
      userId: req.authUser.id,
      type: "converted",
      content: JSON.stringify({ customerId: customer.id, customerBillingId: customerId }),
      createdAt: (/* @__PURE__ */ new Date()).toISOString()
    });
    let workOrder;
    if (createWorkOrder !== false) {
      const ticketNumber = await storage.getNextTicketNumber();
      workOrder = await storage.createTicket({
        ticketNumber,
        title: `Pemasangan Baru - ${lead.name}`,
        categoryId: 1,
        // "Pemasangan Baru" (default seed category)
        customerId: customer.id,
        priority: "medium",
        status: "open",
        createdBy: req.authUser.id,
        address: customer.address || void 0,
        lat: customer.lat ?? void 0,
        lng: customer.lng ?? void 0,
        odpId: lead.odpId ?? void 0,
        estimatedDuration: 120
        // 2 jam default
      });
      await storage.createTicketActivity({
        ticketId: workOrder.id,
        userId: req.authUser.id,
        type: "created",
        content: `Auto-generated dari konversi lead ${lead.name}`,
        createdAt: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    await logAudit(req, "CREATE", "lead_conversion", customer.id, `Lead ${lead.name} \u2192 Customer ${customerId}`);
    await emitLeadEvent("converted", { ...lead, stage: "won" }, req.authUser.id);
    getMetaCapiConfig().then((cfg) => {
      if (cfg) trackPurchase(cfg, {
        name: customer.name,
        phone: customer.phone,
        email: customer.email,
        city: customer.district,
        customerId,
        packageName: pkg,
        value: customer.billingPrice || 0
      }).catch(() => {
      });
    });
    sendSuccess(res, { customer, pppoeSync, workOrder }, 201);
  } catch (e) {
    sendError(res, e.message, 500);
  }
});
