async function applyTicketStatusTransition(req, existing, body) {
  const id = existing.id;
  const { status, resolution, actualDuration } = body;
  const updates = { status };
  if (status === "resolved" || status === "closed") {
    updates.resolvedAt = (/* @__PURE__ */ new Date()).toISOString();
    if (resolution) updates.resolution = resolution;
    if (actualDuration) updates.actualDuration = actualDuration;
    try {
      const cat = existing.categoryId ? await storage.getTicketCategory(existing.categoryId) : null;
      const stages = storage.getCategoryWorkflowStages(cat);
      const finalStage = stages.find((s) => s.isFinal);
      if (finalStage) {
        const transitions = await storage.getTicketStageTransitions(id);
        const finalEntered = transitions.some((t) => t.toStage === finalStage.key);
        if (!finalEntered) updates.legacyResolution = 1;
      }
    } catch (e) {
      console.warn("[A.1] legacy_resolution check fail:", e.message);
    }
  }
  if (status === "closed") updates.closedAt = (/* @__PURE__ */ new Date()).toISOString();
  const ticket = await storage.updateTicket(id, updates);
  if (status === "resolved" || status === "closed") {
    try {
      await storage.scheduleCsatForTicket(id);
    } catch (e) {
      console.warn("[CSAT] schedule fail:", e.message);
    }
  }
  await logTicketActivity(req, id, "status.changed", {
    from: existing.status,
    to: status,
    resolution: resolution ?? null,
    legacyResolution: updates.legacyResolution === 1
  }, `Status: ${existing.status} \u2192 ${status}`);
  await logAudit(req, "UPDATE", "ticket", id, `Status: ${existing.status} \u2192 ${status}`);
  return ticket;
}
