router.post("/api/integrations/chatwoot/webhook", async (req, res) => {
  try {
    const config = await storage.getChatwootConfig();
    if (!config?.enabled) {
      return res.status(200).json({ success: true, ignored: "integration disabled" });
    }
    const signature = req.headers["x-chatwoot-signature"] ?? req.headers["x-chatwoot-webhook-signature"];
    const rawBody = JSON.stringify(req.body);
    const { verifyWebhookSignature: verifyWebhookSignature2, handleConversationCreated: handleConversationCreated2, handleMessageCreated: handleMessageCreated2 } = await Promise.resolve().then(() => (init_chatwoot(), chatwoot_exports));
    if (config.webhookSecret && !verifyWebhookSignature2(rawBody, signature, config.webhookSecret)) {
      console.warn("[Chatwoot] webhook signature invalid");
      return res.status(401).json({ success: false, error: "Invalid signature" });
    }
    const event = req.body?.event;
    let result = { reason: "no handler for event" };
    if (event === "conversation_created") {
      result = await handleConversationCreated2(req.body);
    } else if (event === "message_created") {
      result = await handleMessageCreated2(req.body);
    }
    res.status(200).json({ success: true, event, result });
  } catch (e) {
    console.error("[Chatwoot webhook]", e?.stack ?? e);
    res.status(200).json({ success: false, error: e.message });
  }
});
async function getGenieConfig() {
  const mitraId = tenantContext.getStore()?.mitraId ?? 1;
  const pick2 = async (key) => {
    const own = await storage.getMitraSetting(key, { fallbackToGlobal: false });
    if (own && own.trim() !== "") return own;
    if (mitraId === 1) {
      const g = await storage.getSetting(key);
      if (g && g.trim() !== "") return g;
    }
    return null;
  };
  const host = await pick2("genieacs_host");
  if (!host) throw new Error("GenieACS belum dikonfigurasi untuk mitra ini - atur di Integrasi API");
  const port = await pick2("genieacs_port");
  const username = await pick2("genieacs_username");
  const password = await pick2("genieacs_password");
  return { host, port: Number(port) || 7557, username: username || "", password: password || "" };
}
async function getOpticalThresholds() {
  const mitraId = tenantContext.getStore()?.mitraId ?? 1;
  const pick2 = async (key) => {
    const own = await storage.getMitraSetting(key, { fallbackToGlobal: false });
    if (own && own.trim() !== "") return own;
    if (mitraId === 1) {
      const g = await storage.getSetting(key);
      if (g && g.trim() !== "") return g;
    }
    return null;
  };
  const warn = Number(await pick2("optical_rx_warn"));
  const crit = Number(await pick2("optical_rx_crit"));
  return {
    warn: Number.isFinite(warn) && warn !== 0 ? warn : DEFAULT_OPTICAL_THRESHOLDS.warn,
    crit: Number.isFinite(crit) && crit !== 0 ? crit : DEFAULT_OPTICAL_THRESHOLDS.crit
  };
}
