        id: 0,
        key: spec.key,
        value: spec.isSecret && mitraVal ? "\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022" : mitraVal ?? null,
        category: spec.group?.toLowerCase() ?? "general",
