async function getMpwaClientForDevice(deviceId) {
  const device = await storage.getWaDevice(deviceId);
  if (!device) throw new Error("Device not found");
  if (device.provider !== "mpwa") throw new Error("Endpoint ini hanya untuk provider MPWA");
  let cfg = {};
  try {
    cfg = device.config ? JSON.parse(device.config) : {};
  } catch {
  }
  if (!cfg.apiKey) throw new Error("Device belum punya api_key");
  const { MPWAClient: MPWAClient2 } = await Promise.resolve().then(() => (init_mpwa_client(), mpwa_client_exports));
  return {
    device,
    client: new MPWAClient2({
      apiKey: cfg.apiKey,
      sender: device.phone,
      baseUrl: cfg.url || "https://mpwa.jabnet.id"
    })
  };
}
