customerPortalRouter.get("/api/portal/me", async (req, res) => {
  try {
    const pc = req.portalCustomer;
    const customer = await storage.getCustomer(pc.id);
    if (!customer) return sendErr(res, "Customer tidak ditemukan", 404);
    let sessionInfo = null;
    try {
      if (customer.pppoeUsername) {
        const routers = (await storage.getMikrotikRouters()).filter((r) => r.isActive === 1);
        const settled = await Promise.allSettled(
          routers.map(
            (router2) => getPppActive({
              host: router2.host,
              port: router2.port ?? void 0,
              username: router2.username,
              password: router2.password,
              useSsl: router2.useSsl === 1
            }).then((sessions) => ({ router: router2, sessions }))
          )
        );
        const target = customer.pppoeUsername.toLowerCase();
        for (const result of settled) {
          if (result.status !== "fulfilled") continue;
          const { router: router2, sessions } = result.value;
          const found = sessions.find((s) => String(s.name).toLowerCase() === target);
          if (found) {
            sessionInfo = {
              online: true,
              routerName: router2.name,
              ipAddress: found.address,
              macAddress: found.callerId ?? found["caller-id"],
              uptime: found.uptime,
              sessionId: found.sessionId ?? found.id
            };
            break;
          }
        }
      }
    } catch {
    }
    if (!sessionInfo) sessionInfo = { online: false };
    let ontInfo = null;
    try {
      const geCfg = await getGenieConfig2();
      if (geCfg && customer.pppoeUsername) {
        const device = await findDeviceForCustomer(geCfg, customer.pppoeUsername, customer.ontSerialNumber);
        if (device) {
          ontInfo = {
            matched: true,
            deviceId: device.deviceId,
            status: device.status,
            serialNumber: device.serialNumber,
            manufacturer: device.manufacturer,
            model: device.productClass,
            rxPower: device.rxPower,
            ipAddress: device.ipAddress,
            lastInform: device.lastInform,
            uptime: device.uptime
          };
        }
      }
    } catch (e) {
      console.warn("[portal/me] ONT lookup error:", e.message);
    }
    if (!ontInfo) ontInfo = { matched: false };
    sendOk(res, {
      customer: {
        id: customer.id,
        customerId: customer.customerId,
        name: customer.name,
        phone: customer.phone,
        email: customer.email,
        address: customer.address,
        package: customer.package,
        pppoeUsername: customer.pppoeUsername,
        status: customer.status,
        isIsolir: customer.isIsolir
      },
      pppoe: sessionInfo,
      ont: ontInfo
    });
  } catch (e) {
    sendErr(res, e.message, 500);
  }
});
